"use client";

import { useEffect, useState } from "react";

export type MascotMood = "welcome" | "focus" | "correct" | "oops" | "celebrate";

/**
 * The tin whistle donkey. It is decorative: every state it shows is also
 * given in text next to it, so screen readers skip it.
 * The images come from public/mascot (generated by `npm run brand:assets`).
 */
export function Mascot({ mood, size = 88, className = "" }: { mood: MascotMood; size?: number; className?: string }) {
  // Keying the image on the mood replays the small entrance animation on every change.
  return (
    // A plain image keeps the same markup on the web, static Pages and the mobile bundle.
    // eslint-disable-next-line @next/next/no-img-element
    <img key={mood} src={`mascot/${mood}.svg`} alt="" aria-hidden="true" width={size} height={size}
      className={`mascot mascot-${mood} ${className}`.trim()} draggable={false} />
  );
}

/** Shows a short reaction (correct or oops) and then returns to the resting mood. */
export function useMascotReaction(resting: MascotMood, holdMs = 1200) {
  const [reaction, setReaction] = useState<{ mood: MascotMood; id: number } | null>(null);
  useEffect(() => {
    if (!reaction) return;
    const timer = window.setTimeout(() => setReaction(null), holdMs);
    return () => window.clearTimeout(timer);
  }, [holdMs, reaction]);
  return {
    mood: reaction?.mood ?? resting,
    react: (mood: MascotMood) => setReaction({ mood, id: Date.now() }),
  };
}
